function addRampVisual(root,r){const mesh=box(root,'#c28a35',r.x,(r.topY[0]+r.topY[2])*.5-.04,r.z,r.width,.18,r.length);mesh.rotation.order='YXZ';mesh.rotation.y=r.yaw;mesh.rotation.x=-Math.atan2(r.rise,r.length);}
