function ensureOverlay(){if(typeof document==='undefined')return null;let root=document.getElementById('tangenzialeRaceUi');if(root)return root;root=document.createElement('div');root.id='tangenzialeRaceUi';root.style.cssText='position:fixed;inset:0;z-index:45;pointer-events:none;font-family:Inter,system-ui,sans-serif;color:white;text-shadow:0 2px 8px #000';root.innerHTML='<div id="tangenzialeCountdown" style="position:absolute;left:50%;top:24%;transform:translate(-50%,-50%);font-size:96px;font-weight:900;letter-spacing:.04em"></div><div id="tangenzialeBoard" style="position:absolute;right:22px;top:80px;min-width:260px;background:rgba(10,14,18,.78);border:1px solid rgba(255,255,255,.22);border-radius:12px;padding:12px 14px;font-size:13px;line-height:1.55"></div><div style="position:absolute;left:50%;bottom:24px;transform:translateX(-50%);background:rgba(10,14,18,.72);padding:8px 13px;border-radius:10px;font-size:13px">SHIFT · TURBO ×3 &nbsp;·&nbsp; X · ABBANDONA GARA</div>';document.body.appendChild(root);return root;}
function hideOverlay(){if(typeof document!=='undefined')document.getElementById('tangenzialeRaceUi')?.remove();}

export class TangenzialeRace{
 constructor(game){this.game=game;this.race=null;this.routeCache=null;this.keyDown=this.keyDown.bind(this);this.keyUp=this.keyUp.bind(this);if(typeof window!=='undefined'){window.addEventListener('keydown',this.keyDown,true);window.addEventListener('keyup',this.keyUp,true);}}
 keyDown(e){const r=this.race;if(!r)return;if(e.code==='KeyX'){e.preventDefault();e.stopImmediatePropagation();if(r.phase==='results')this.finalizeResult();else this.abort();return;}if(r.phase==='countdown'&&BLOCKED_DURING_COUNTDOWN.has(e.code)){e.preventDefault();e.stopImmediatePropagation();return;}if(['KeyE','KeyJ','KeyV','KeyM'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();if(e.code==='KeyE')this.game.toast('Non puoi scendere dall’auto durante la gara.',1.5);return;}if(!['ShiftLeft','ShiftRight'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat||r.phase!=='running'||r.playerFinished||r.playerTurboUntil>this.game.state.elapsed)return;if(r.playerTurbo<=0){this.game.toast('Turbo esauriti · continua senza boost.',1.5);return;}r.playerTurbo--;r.playerTurboUntil=this.game.state.elapsed+TURBO_SECONDS;this.game.toast('TURBO · '+r.playerTurbo+' rimasti',1.5);}
 keyUp(e){if(!this.race||!['ShiftLeft','ShiftRight'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation();}
 openConfirmation(){const game=this.game;if(this.race)return;if(game.state.mission){game.toast('Concludi o annulla la missione attiva prima della gara.',4);document.getElementById('menu')?.close();game.state.paused=false;return;}const menu=document.getElementById('menu'),title=document.getElementById('menuTitle'),content=document.getElementById('menuContent');if(!menu||!content)return;if(title)title.textContent='Gara in tangenziale';content.innerHTML='<p class="about-copy"><strong>Sei sicuro di voler iniziare?</strong><br>Verrai teletrasportato automaticamente sulla tangenziale. 4 Fulmine R identiche, 3 turbo su <kbd>SHIFT</kbd>, rampe, camion e traffico da schivare.<br><strong>Vittoria +€350 · sconfitta -€100.</strong><br>Durante la gara: <kbd>X</kbd> abbandona e torna esattamente alla situazione precedente.</p><div class="menu-actions"><button class="primary" id="startTangenzialeRace">INIZIA GARA</button><button id="cancelTangenzialeRace">ANNULLA</button></div>';document.getElementById('startTangenzialeRace').onclick=()=>this.start();document.getElementById('cancelTangenzialeRace').onclick=()=>{menu.close();game.state.paused=false;};}
 snapshot(){const s=this.game.state,c=s.car;return {mode:s.mode,x:s.x,z:s.z,y:s.y,yaw:s.yaw,speed:s.speed,vy:s.vy,health:s.health,wanted:s.wanted,escape:s.escape,busted:s.busted,paused:s.paused,camera:s.camera,car:c,waypoint:s.waypoint,route:Array.isArray(s.route)?s.route.map(p=>({...p})):[],carPose:c?{x:c.x,z:c.z,y:c.y,yaw:c.yaw,speed:c.speed,health:c.health,parked:c.parked,visible:c.mesh.visible}:null,gameGraceUntil:this.game.graceUntil};}
 start(){const game=this.game,s=game.state,raw=this.routeCache||chooseRaceRoute(game);if(!raw){game.toast('Tangenziale non disponibile in questa versione della rete stradale.',5);return;}this.routeCache=raw;const samples=prepareSamples(game,raw);if(samples.length<70||samples.total<1800){game.toast('Tratto di tangenziale troppo corto per avviare la gara.',5);return;}document.getElementById('menu')?.close();s.paused=false;const snapshot=this.snapshot();if(snapshot.car){snapshot.car.parked=true;snapshot.car.speed=0;game.pose(snapshot.car);}const startIndex=chooseStartIndex(game,samples),start=samples[startIndex],startYaw=yawAt(samples,startIndex),finish=samples.at(-2),finishYaw=yawAt(samples,samples.length-2),startDistance=samples.cumulative[startIndex]||0,total=Math.max(1,samples.total-startDistance),race={phase:'countdown',countdownAt:s.elapsed,startedAt:null,snapshot,samples,total,startDistance,startIndex,start,startYaw,finish,finishYaw,playerCar:null,ai:[],obstacles:[],roots:[],ramps:[],playerTurbo:TURBO_CHARGES,playerTurboUntil:0,playerHint:startIndex,playerProgress:0,playerCheckpoint:startIndex,playerFinished:false,finishTimes:[null,null,null,null],finishOrder:[],firstFinishAt:null,resultUntil:null,resultApplied:false,finished:false};const obstacleDefs=[{index:safeFeatureIndex(samples,startIndex,.30),offset:0,style:'truck',yawOffset:.02,label:'CAMION'},{index:safeFeatureIndex(samples,startIndex,.52),offset:1.55,style:'wagon',yawOffset:-.04,label:'AUTO FERMA'},{index:safeFeatureIndex(samples,startIndex,.78),offset:-1.45,style:'utility',yawOffset:.05,label:'FURGONE'}];race.obstacleDefs=obstacleDefs;const cars=[];for(let i=0;i<AI_COUNT+1;i++){const p=gridPose(game,race,START_GRID[i]),c=game.addCar(p.x,p.z,startYaw,false,true,RACER_STYLE);Object.assign(c,{x:p.x,z:p.z,y:p.y,yaw:startYaw,speed:0,health:100,parked:true,missionUnit:true,fixedSpawn:true,tangenzialeRace:true,budgetSleeping:false});addLivery(c,i);game.pose(c);cars.push(c);}race.playerCar=cars[0];game.claim(race.playerCar);Object.assign(race.playerCar,{missionUnit:true,fixedSpawn:true,tangenzialeRace:true,budgetSleeping:false});const skills=[.975,.995,1.012],offsets=[1.35,-1.25,.12];for(let i=0;i<AI_COUNT;i++){const c=cars[i+1],line=routeWithDetours(samples,offsets[i],obstacleDefs);Object.assign(c,{parked:true,path:line,pathIndex:startIndex+1,stuck:0,raceSkill:skills[i],raceTurbo:TURBO_CHARGES,raceTurboIndex:0,raceTurboUntil:0,raceHint:startIndex,raceProgress:0,raceCheckpoint:startIndex,raceIndex:i+1,raceOffset:offsets[i],raceFinished:false,budgetSleeping:false});race.ai.push(c);}for(const o of obstacleDefs){const p=samples[o.index],yaw=yawAt(samples,o.index)+o.yawOffset,q=lateral(p,yawAt(samples,o.index),o.offset),c=game.addCar(q.x,q.z,yaw,false,true,o.style);Object.assign(c,{x:q.x,z:q.z,y:trackHeight(game,p,q.x,q.z,p.y),yaw,speed:0,parked:true,missionUnit:true,fixedSpawn:true,tangenzialeObstacle:true,budgetSleeping:false,name:o.label});c.mesh.visible=true;game.pose(c);race.obstacles.push(c);}const rampRoot=new THREE.Group();rampRoot.name='tangenziale-race-ramps';for(const [fraction,side] of [[.20,-1],[.44,1],[.68,-1],[.88,1]]){const index=safeFeatureIndex(samples,startIndex,fraction),r=buildRamp(game,samples,index,side);race.ramps.push(r);addRampVisual(rampRoot,r);}game.terrain.arcadeRamps=[...(game.terrain.arcadeRamps||[]),...race.ramps];game.scene.add(rampRoot);race.roots.push(rampRoot);race.startSet=buildStartSet(game,start,startYaw);race.finishSet=buildFinishSet(game,finish,finishYaw);race.roots.push(race.startSet.root,race.finishSet);Object.assign(s,{mode:'car',car:race.playerCar,x:race.playerCar.x,z:race.playerCar.z,y:race.playerCar.y,yaw:startYaw,speed:0,vy:0,health:100,wanted:0,escape:0,busted:0,waypoint:{x:finish.x,z:finish.z,name:'TRAGUARDO · Tangenziale'},route:samples.slice(startIndex).map(p=>({x:p.x,z:p.z}))});resetGroundMotion(race.playerCar);this.race=race;activeManager=this;game.graceUntil=Infinity;ensureOverlay();game.toast('GARA TANGENZIALE · 5, 4, 3, 2, 1. Acceleratore bloccato fino al VIA.',4);this.paintHud();}
 ensureRacer(c,index,offset){const r=this.race,g=this.game;if(!g.cars.includes(c))g.cars.push(c);if(!c.mesh.parent)g.scene.add(c.mesh);c.mesh.visible=true;c.missionUnit=true;c.fixedSpawn=true;c.tangenzialeRace=true;c.budgetSleeping=false;if(c.health<=0||!Number.isFinite(c.x)||!Number.isFinite(c.z)){this.respawnActor(c,respawnCheckpoint(r.startIndex,c.raceCheckpoint??r.startIndex,r.samples.length),offset);c.health=100;}c.raceIndex=index;}
 freezeGrid(){const r=this.race,s=this.game.state,c=r.playerCar,all=[c,...r.ai];for(let i=0;i<all.length;i++){const a=all[i],p=gridPose(this.game,r,START_GRID[i]);this.ensureRacer(a,i,i?([-1.25,0,1.25][i-1]):-1);Object.assign(a,{x:p.x,z:p.z,y:p.y,yaw:r.startYaw,speed:0,health:100,parked:true});resetGroundMotion(a);this.game.pose(a);}Object.assign(s,{x:c.x,z:c.z,y:c.y,yaw:c.yaw,speed:0,vy:0,health:100});}
 countdown(){const r=this.race,t=this.game.state.elapsed-r.countdownAt;this.freezeGrid();const value=countdownValue(t),lit=Math.min(4,Math.max(0,COUNTDOWN_SECONDS-value));for(let i=0;i<r.startSet.lights.length;i++)r.startSet.lights[i].material=material(i<=lit?'#ff263d':'#3b171b',true);if(r.startSet.flag)r.startSet.flag.rotation.z=-.08+Math.sin(t*4)*.025;this.paintHud(value);if(t>=COUNTDOWN_SECONDS){for(const lamp of r.startSet.lights)lamp.material=material('#151719',true);if(r.startSet.flag)r.startSet.flag.rotation.z=-.72;r.phase='running';r.startedAt=this.game.state.elapsed;for(const c of [r.playerCar,...r.ai])c.parked=false;this.game.toast('VIA! · SHIFT = turbo · 3 cariche · X = abbandona',3);this.paintHud('VIA!');}}
 applyPlayerTurbo(dt){const r=this.race,s=this.game.state;if(r.playerFinished||s.elapsed>=r.playerTurboUntil)return;const cap=r.playerCar.spec.max*1.11;s.speed=Math.min(cap,s.speed+8.5*dt);r.playerCar.speed=s.speed;}
 updateCheckpoint(actor,p,indexKey,checkpointKey){const r=this.race,previous=actor[indexKey]??r.startIndex;actor[indexKey]=p.index;if(p.d<=15)actor[checkpointKey]=nextCheckpoint(r.startIndex,actor[checkpointKey]??r.startIndex,p.index,previous);}
 updateAI(dt){const r=this.race,traffic=[r.playerCar,...r.ai,...r.obstacles];for(const [i,c] of r.ai.entries()){this.ensureRacer(c,i+1,c.raceOffset??[-1.2,0,1.2][i]);if(c.raceFinished){c.speed=0;c.parked=true;this.game.pose(c);continue;}const p=nearestSample(c,r.samples,c.raceHint||r.startIndex);this.updateCheckpoint(c,p,'raceHint','raceCheckpoint');c.raceProgress=Math.max(c.raceProgress||0,progressAt(r,p.index));if(c.raceProgress>=r.total-28||dist(c,r.finish)<18){this.markFinished(i+1,c);continue;}const frac=c.raceProgress/r.total,plans=[[.18,.49,.79],[.23,.55,.83],[.15,.45,.74]][i];if(c.raceTurbo>0&&c.raceTurboIndex<plans.length&&frac>=plans[c.raceTurboIndex]){c.raceTurbo--;c.raceTurboIndex++;c.raceTurboUntil=this.game.state.elapsed+TURBO_SECONDS;}const boost=this.game.state.elapsed<c.raceTurboUntil,max=c.spec.max*c.raceSkill+(boost?6.2:0);followRoad(c,dt,this.game.graph,this.game.terrain,this.game.collision,{max,accel:14.4+i*.3,turnRate:1.78,traffic:traffic.filter(o=>o!==c)});this.game.pose(c);if(p.d>TRACK_LIMIT||c.stuck>4.2)this.respawnActor(c,respawnCheckpoint(r.startIndex,c.raceCheckpoint,r.samples.length),c.raceOffset);}}
 respawnActor(car,index,offset=0){const r=this.race,i=respawnCheckpoint(r.startIndex,index,r.samples.length),p=r.samples[i],yaw=yawAt(r.samples,i),q=lateral(p,yaw,offset),y=trackHeight(this.game,p,q.x,q.z,p.y);Object.assign(car,{x:q.x,z:q.z,y,yaw,speed:0,health:100,stuck:0,parked:false,pathIndex:Math.min(r.samples.length-1,i+1),budgetSleeping:false,missionUnit:true,fixedSpawn:true});resetGroundMotion(car);car.mesh.visible=true;if(!car.mesh.parent)this.game.scene.add(car.mesh);this.game.pose(car);if(car===r.playerCar)Object.assign(this.game.state,{x:car.x,z:car.z,y:car.y,yaw:car.yaw,speed:0,vy:0,health:100});}
 updatePlayer(){const r=this.race,s=this.game.state;if(r.playerFinished){Object.assign(s,{speed:0,vy:0});r.playerCar.speed=0;r.playerCar.parked=true;this.game.pose(r.playerCar);return true;}if(s.car!==r.playerCar||s.mode!=='car'){this.respawnActor(r.playerCar,respawnCheckpoint(r.startIndex,r.playerCheckpoint,r.samples.length),-1.2);s.car=r.playerCar;s.mode='car';this.game.toast('Gara ripristinata · torni in pista.',2);return true;}if(s.health<=0){this.respawnActor(r.playerCar,respawnCheckpoint(r.startIndex,r.playerCheckpoint,r.samples.length),-1.2);this.game.toast('Auto ripristinata all’ultimo checkpoint.',2.5);return true;}const previous=r.playerHint,p=nearestSample(s,r.samples,r.playerHint);r.playerHint=p.index;r.playerProgress=Math.max(r.playerProgress,progressAt(r,p.index));if(p.d<=15)r.playerCheckpoint=nextCheckpoint(r.startIndex,r.playerCheckpoint,p.index,previous);if(p.d>TRACK_LIMIT||s.x<-5970||s.x>7250||s.z<-6480||s.z>6230){this.respawnActor(r.playerCar,respawnCheckpoint(r.startIndex,r.playerCheckpoint,r.samples.length),-1.2);this.game.toast('Fuori tracciato · respawn all’ultimo checkpoint valido.',2.5);}if(r.playerProgress>=r.total-28||dist(s,r.finish)<18)this.markFinished(0,r.playerCar);return true;}
 markFinished(index,car){const r=this.race;if(r.finishTimes[index]!==null)return;const time=Math.max(0,this.game.state.elapsed-r.startedAt);r.finishTimes[index]=time;r.finishOrder.push(index);if(r.firstFinishAt===null)r.firstFinishAt=this.game.state.elapsed;car.raceFinished=true;car.speed=0;car.parked=true;if(index===0){r.playerFinished=true;this.game.state.speed=0;this.game.state.vy=0;this.game.toast('TRAGUARDO · tempo '+formatRaceTime(time),3);}else this.game.toast('Auto '+(index+1)+' al traguardo · '+formatRaceTime(time),2);}
 rank(){const r=this.race,values=[{player:true,p:r.playerProgress},...r.ai.map(c=>({player:false,p:c.raceProgress||0}))].sort((a,b)=>b.p-a.p);return values.findIndex(v=>v.player)+1;}
 raceBoard(){const r=this.race,elapsed=r.startedAt===null?0:Math.max(0,this.game.state.elapsed-r.startedAt),progress=[r.playerProgress,...r.ai.map(c=>c.raceProgress||0)];return progress.map((p,i)=>{const place=r.finishOrder.indexOf(i),time=r.finishTimes[i],status=time!==null?('#'+(place+1)+' · '+formatRaceTime(time)):(formatRaceTime(elapsed)+' · '+Math.round(Math.min(100,p/r.total*100))+'%');return '<div><strong>'+(i===0?'AUTO 1 · TU':'AUTO '+(i+1))+'</strong><span style="float:right;margin-left:18px">'+status+'</span></div>';}).join('');}
 paintHud(center=null){const r=this.race;if(!r)return;queueMicrotask(()=>{if(!this.race)return;const type=document.getElementById('missionType'),title=document.getElementById('missionTitle'),desc=document.getElementById('missionDesc'),timer=document.getElementById('missionTimer'),ui=ensureOverlay(),count=ui?.querySelector('#tangenzialeCountdown'),board=ui?.querySelector('#tangenzialeBoard');if(type)type.textContent='GARA TANGENZIALE';if(title)title.textContent=r.phase==='countdown'?'PARTENZA BLOCCATA':r.phase==='results'?(r.finishOrder[0]===0?'VITTORIA':'SCONFITTA'):'Posizione '+this.rank()+' / 4';if(desc)desc.textContent='Fulmine R · Turbo '+r.playerTurbo+'/3 · SHIFT · X abbandona · '+Math.round(Math.min(100,r.playerProgress/r.total*100))+'%';if(timer)timer.textContent=r.phase==='running'?formatRaceTime(this.game.state.elapsed-r.startedAt):r.phase==='countdown'?'5 → 1':'RISULTATI';if(count)count.textContent=center!==null?String(center):(r.phase==='results'?(r.finishOrder[0]===0?'VITTORIA':'SCONFITTA'):'');if(board)board.innerHTML='<div style="font-size:11px;opacity:.7;letter-spacing:.08em;margin-bottom:5px">TEMPI GARA</div>'+this.raceBoard();});}
 resolveIfReady(){const r=this.race;if(!resultsReady(this.game.state.elapsed,r.firstFinishAt,r.finishTimes))return false;const win=r.finishOrder[0]===0;this.applyResult(win);return true;}
 applyResult(win){const r=this.race;if(!r||r.resultApplied)return;r.resultApplied=true;r.phase='results';const s=this.game.state;s.money+=win?WIN_REWARD:-LOSE_PENALTY;saveMoney(s);r.resultMoney=s.money;r.resultWin=win;r.resultUntil=s.elapsed+6;for(const c of [r.playerCar,...r.ai]){c.speed=0;c.parked=true;}this.game.toast(win?'VITTORIA · +€350':'SCONFITTA · -€100',6);this.paintHud();}
 finalizeResult(){const r=this.race;if(!r)return;const money=r.resultMoney??this.game.state.money;this.restoreSnapshot();this.game.state.money=money;saveMoney(this.game.state);}
 abort(){const r=this.race;if(!r)return;this.restoreSnapshot();this.game.toast('Gara abbandonata · situazione precedente ripristinata.',4);}
 restoreSnapshot(){const r=this.race;if(!r)return;const game=this.game,s=game.state,snap=r.snapshot;game.terrain.arcadeRamps=(game.terrain.arcadeRamps||[]).filter(x=>!x.tangenzialeRace);for(const root of r.roots)game.scene.remove(root);for(const c of [...r.ai,r.playerCar,...r.obstacles]){if(!c||c===snap.car)continue;try{game.retire(c);}catch{game.remove(c);}}this.race=null;hideOverlay();game.graceUntil=snap.gameGraceUntil;const c=snap.car;if(c&&snap.carPose){Object.assign(c,snap.carPose);c.mesh.visible=snap.carPose.visible;resetGroundMotion(c);game.pose(c);}Object.assign(s,{mode:snap.mode,x:snap.x,z:snap.z,y:snap.y,yaw:snap.yaw,speed:snap.speed,vy:snap.vy,health:snap.health,wanted:snap.wanted,escape:snap.escape,busted:snap.busted,paused:snap.paused,camera:snap.camera,car:c||null,waypoint:snap.waypoint,route:snap.route});activeManager=this;}
 update(dt){activeManager=this;const r=this.race;if(!r)return;if(r.phase==='countdown'){this.countdown();return;}if(r.phase==='results'){this.paintHud();if(this.game.state.elapsed>=r.resultUntil)this.finalizeResult();return;}if(r.phase!=='running')return;this.applyPlayerTurbo(dt);this.updateAI(dt);if(!this.updatePlayer())return;this.game.state.wanted=0;this.game.state.escape=0;if(this.resolveIfReady())return;this.paintHud();}
}
function decorateActivities(){if(typeof document==='undefined')return;const content=document.getElementById('menuContent'),title=document.getElementById('menuTitle');if(!content||!/A little extra on the side\./i.test(title?.textContent||''))return;const list=content.querySelector('.activities');if(!list||document.getElementById('tangenzialeRaceActivity'))return;const b=document.createElement('button');b.id='tangenzialeRaceActivity';b.className='activity';b.innerHTML='<span class="icon">⚑</span><span><b>'+RACE_LABEL+'</b><small>4 Fulmine R · 3 turbo SHIFT · rampe · camion · tempi live</small></span><span class="reward">+€350</span>';b.onclick=()=>activeManager?.openConfirmation();list.appendChild(b);}
if(typeof document!=='undefined'&&typeof MutationObserver!=='undefined')new MutationObserver(decorateActivities).observe(document.getElementById('menuContent')||document.body,{childList:true,subtree:true});
const originalUpdate=ModernGameplay.prototype.update;
if(!ModernGameplay.prototype.__tangenzialeRace){ModernGameplay.prototype.__tangenzialeRace=true;ModernGameplay.prototype.update=function(dt){originalUpdate.call(this,dt);let m=managers.get(this);if(!m){m=new TangenzialeRace(this);managers.set(this,m);}m.update(dt);};}
